def infer_operands_size(operands):
    """Infer x86 instruction operand size based on other operands.
    """
    size = None

    for oprnd in operands:
        if oprnd.size:
            size = oprnd.size
            break

    if size:
        for oprnd in operands:
            if not oprnd.size:
                oprnd.size = size
    else:
        for oprnd in operands:
            if isinstance(oprnd, X86ImmediateOperand) and not oprnd.size:
                oprnd.size = arch_info.architecture_size

class ExecutionCache(object):

    def __init__(self):
        self.__container = {}

    def add(self, address, instruction, container):
        # NOTE Does not take into account self modifying code.
        if address in self.__container:
            raise Exception("Invalid instruction")

        self.__container[address] = (instruction, container)

    def retrieve(self, address):
        if address not in self.__container:
            # print("cache miss!")
            raise InvalidAddressError()

        # print("cache hit!")

        return self.__container[address]
